-- Nurse Love Company: complete database setup for Supabase.
--
-- How to use: Supabase dashboard, SQL Editor, New query. Paste this whole
-- file, click Run, and wait for "Success". Run it ONCE on a new, empty
-- project. If the store's tables already exist it stops without changing
-- anything.
--
-- Generated by `npm run db:sql` from server/db/migrations. Do not edit by
-- hand. Everything runs in one transaction: it either all applies or none
-- of it does.

begin;

do $$ begin
  if to_regclass('public.schema_migrations') is not null then
    raise exception 'This database is already set up (schema_migrations exists). Nothing was changed.';
  end if;
end $$;

-- 1. Accounts and sign in sessions (Better Auth)
create table "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "role" text not null);

create table "session" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);

create table "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "rateLimit" ("id" text not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);

create index "session_userId_idx" on "session" ("userId");

create index "account_userId_idx" on "account" ("userId");

create index "verification_identifier_idx" on "verification" ("identifier");

-- 2. The store
create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now());

-- 001_core.sql
-- Nurse Love Company store schema.
-- Better Auth owns the "user", "session", "account" and "verification" tables
-- (created by server/db/migrate.ts). Everything below belongs to the store.

create extension if not exists pgcrypto;

-- Settings ------------------------------------------------------------------
create table app_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by text
);

-- Customers -----------------------------------------------------------------
create table customer_profiles (
  user_id text primary key references "user"(id) on delete cascade,
  order_updates boolean not null default true,
  product_updates boolean not null default true,
  marketing boolean not null default false,
  admin_notes text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table addresses (
  id uuid primary key default gen_random_uuid(),
  user_id text not null references "user"(id) on delete cascade,
  name text not null,
  line1 text not null,
  line2 text not null default '',
  city text not null,
  region text not null default '',
  postal_code text not null,
  country text not null default 'US',
  phone text not null default '',
  is_default boolean not null default false,
  created_at timestamptz not null default now()
);
create index addresses_user_idx on addresses(user_id);

-- Products ------------------------------------------------------------------
create table products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null check (length(title) between 1 and 160),
  category text not null check (category in ('nurse-inserts','np-inserts','apparel','accessories','pens','other')),
  collection text not null default '',
  type text not null check (type in ('digital','physical')),
  short_description text not null default '',
  description jsonb not null default '{"type":"doc","content":[]}',
  price_cents integer check (price_cents >= 0),
  sale_price_cents integer check (sale_price_cents >= 0),
  currency text not null default 'usd',
  featured boolean not null default false,
  active boolean not null default true,
  status text not null default 'draft' check (status in ('draft','published')),
  archived_at timestamptz,
  sort_order integer not null default 0,
  is_demo boolean not null default false,
  -- digital
  page_count integer check (page_count > 0),
  page_size text,
  orientation text check (orientation in ('portrait','landscape')),
  file_format text,
  usage_attributes text[] not null default '{}',
  app_compatibility text[] not null default '{}',
  show_binder_notice boolean not null default false,
  current_version_id uuid,
  -- physical
  sku text unique,
  weight_grams integer check (weight_grams >= 0),
  shipping_info text not null default '',
  inventory_quantity integer not null default 0,
  low_stock_threshold integer not null default 3,
  out_of_stock_behavior text not null default 'show_sold_out' check (out_of_stock_behavior in ('hide','show_sold_out','allow_backorder')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  check (sale_price_cents is null or (price_cents is not null and sale_price_cents < price_cents))
);

create table product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  title text not null,
  options jsonb not null default '{}',
  sku text unique,
  price_cents integer check (price_cents >= 0),
  inventory_quantity integer not null default 0,
  sort_order integer not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create index product_variants_product_idx on product_variants(product_id);

create table product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  variant_id uuid references product_variants(id) on delete set null,
  kind text not null default 'gallery' check (kind in ('gallery','sample')),
  storage_key text not null,
  content_type text not null,
  width integer,
  height integer,
  alt text not null default '',
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);
create index product_images_product_idx on product_images(product_id, kind, sort_order);

-- Released digital files. Rows are immutable once inserted.
create table product_versions (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id),
  version_number integer not null,
  storage_key text not null,
  file_name text not null,
  content_type text not null,
  file_size bigint not null check (file_size > 0),
  sha256 text not null,
  notes text not null default '',
  released_at timestamptz not null default now(),
  released_by text,
  unique (product_id, version_number)
);
alter table products add constraint products_current_version_fk foreign key (current_version_id) references product_versions(id);

-- Uploaded but not yet released product files (staging area for releases).
create table product_file_uploads (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id),
  storage_key text not null,
  file_name text not null,
  content_type text not null,
  file_size bigint not null,
  sha256 text not null,
  uploaded_by text,
  created_at timestamptz not null default now(),
  released_version_id uuid references product_versions(id)
);

create table product_releases (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id),
  version_id uuid not null unique references product_versions(id),
  idempotency_key text not null unique,
  notify boolean not null default false,
  affected_count integer not null default 0,
  granted_count integer not null default 0,
  created_by text,
  created_at timestamptz not null default now()
);

create or replace function forbid_change() returns trigger language plpgsql as $$
begin
  raise exception '% rows are immutable', tg_table_name;
end $$;
create trigger product_versions_immutable before update or delete on product_versions
  for each row execute function forbid_change();

-- Orders --------------------------------------------------------------------
create sequence order_number_seq start 10001;

create table orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique default ('NLC-' || nextval('order_number_seq')),
  user_id text references "user"(id) on delete set null,
  email text not null,
  customer_name text not null default '',
  status text not null default 'pending' check (status in ('pending','paid','failed','canceled','refunded','partially_refunded','disputed')),
  fulfillment_status text not null default 'unfulfilled' check (fulfillment_status in ('unfulfilled','partially_fulfilled','fulfilled','not_required')),
  currency text not null default 'usd',
  subtotal_cents integer not null default 0,
  discount_cents integer not null default 0,
  shipping_cents integer not null default 0,
  tax_cents integer not null default 0,
  total_cents integer not null default 0,
  fee_cents integer,
  refunded_cents integer not null default 0,
  billing_details jsonb not null default '{}',
  shipping_address jsonb,
  stripe_checkout_session_id text unique,
  stripe_payment_intent_id text unique,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  paid_at timestamptz,
  canceled_at timestamptz,
  updated_at timestamptz not null default now()
);
create index orders_user_idx on orders(user_id, created_at desc);
create index orders_created_idx on orders(created_at desc);

create table order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id) on delete restrict,
  product_id uuid not null references products(id) on delete restrict,
  variant_id uuid references product_variants(id) on delete restrict,
  product_type text not null check (product_type in ('digital','physical')),
  title_snapshot text not null,
  variant_snapshot text not null default '',
  sku_snapshot text not null default '',
  category_snapshot text not null default '',
  unit_price_cents integer not null,
  quantity integer not null check (quantity > 0),
  discount_cents integer not null default 0,
  line_total_cents integer not null,
  refunded_quantity integer not null default 0,
  version_id_at_purchase uuid references product_versions(id),
  -- Digital products default to quantity one until the business decides otherwise.
  check (product_type = 'physical' or quantity = 1)
);
create index order_items_order_idx on order_items(order_id);
create index order_items_product_idx on order_items(product_id);

create table refunds (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id),
  amount_cents integer not null check (amount_cents > 0),
  reason text not null default '',
  stripe_refund_id text unique,
  status text not null default 'pending' check (status in ('pending','succeeded','failed','canceled')),
  -- Which lines and quantities this refund covers: [{"order_item_id": "...", "quantity": 1}]
  items jsonb not null default '[]',
  restock boolean not null default false,
  failure_reason text not null default '',
  idempotency_key text unique,
  created_by text,
  created_at timestamptz not null default now()
);

create table shipments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id),
  carrier text not null default '',
  tracking_number text not null default '',
  tracking_url text not null default '',
  status text not null default 'shipped' check (status in ('label_created','shipped','in_transit','delivered','exception')),
  shipped_at timestamptz,
  delivered_at timestamptz,
  created_by text,
  created_at timestamptz not null default now()
);

create table order_updates (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id),
  message text not null,
  customer_visible boolean not null default true,
  created_by text,
  created_at timestamptz not null default now()
);

create table order_notes (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references orders(id),
  body text not null,
  author_id text,
  author_email text,
  created_at timestamptz not null default now()
);

-- Verified payment provider events, stored once (idempotency).
create table payment_events (
  id text primary key,
  type text not null,
  payload jsonb not null,
  status text not null default 'received' check (status in ('received','processed','ignored','failed')),
  error text,
  received_at timestamptz not null default now(),
  processed_at timestamptz
);

-- Download entitlements -----------------------------------------------------
create table entitlements (
  id uuid primary key default gen_random_uuid(),
  user_id text not null references "user"(id) on delete cascade,
  product_id uuid not null references products(id),
  order_item_id uuid not null references order_items(id),
  version_id uuid not null references product_versions(id),
  source text not null check (source in ('purchase','update','admin_replacement')),
  status text not null default 'available' check (status in ('available','redeemed','superseded','revoked')),
  release_id uuid references product_releases(id),
  reason text not null default '',
  granted_by text,
  granted_at timestamptz not null default now(),
  redeemed_at timestamptz,
  status_changed_at timestamptz not null default now(),
  check (source <> 'admin_replacement' or length(reason) > 0)
);
-- Never more than one unredeemed download per purchased item: no stacking.
create unique index entitlements_one_available on entitlements(order_item_id) where status = 'available';
-- A purchase or an update grants at most one entitlement per version, even if retried.
create unique index entitlements_once_per_version on entitlements(order_item_id, version_id) where source in ('purchase','update');
create index entitlements_user_idx on entitlements(user_id);

create table download_tokens (
  id uuid primary key default gen_random_uuid(),
  token_hash text not null unique,
  entitlement_id uuid not null references entitlements(id),
  user_id text not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  used_at timestamptz,
  ip text,
  user_agent text
);

create table download_events (
  id bigserial primary key,
  entitlement_id uuid references entitlements(id),
  user_id text,
  version_id uuid,
  event text not null,
  detail text not null default '',
  ip text,
  user_agent text,
  created_at timestamptz not null default now()
);
create index download_events_ent_idx on download_events(entitlement_id);

create table download_problem_reports (
  id uuid primary key default gen_random_uuid(),
  entitlement_id uuid not null references entitlements(id),
  user_id text not null,
  message text not null,
  status text not null default 'open' check (status in ('open','resolved','declined')),
  resolution_note text not null default '',
  resolved_by text,
  resolved_at timestamptz,
  created_at timestamptz not null default now()
);

create table support_requests (
  id uuid primary key default gen_random_uuid(),
  user_id text not null references "user"(id) on delete cascade,
  order_id uuid references orders(id),
  subject text not null,
  message text not null,
  status text not null default 'open' check (status in ('open','closed')),
  created_at timestamptz not null default now()
);

-- Email ---------------------------------------------------------------------
create table email_templates (
  type text primary key,
  subject text not null,
  heading text not null,
  body text not null,
  button_label text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text
);

create table emails (
  id uuid primary key default gen_random_uuid(),
  type text not null,
  to_email text not null,
  subject text not null,
  html text not null,
  text_body text not null default '',
  related_user_id text,
  related_order_id uuid references orders(id),
  related_release_id uuid references product_releases(id),
  status text not null default 'queued' check (status in ('queued','sending','sent','delivered','delivery_delayed','bounced','complained','failed','suppressed','not_configured')),
  resend_id text unique,
  idempotency_key text not null unique,
  resent_from_id uuid references emails(id),
  resent_by text,
  attempts integer not null default 0,
  failure_reason text not null default '',
  requested_at timestamptz not null default now(),
  sent_at timestamptz,
  delivered_at timestamptz,
  bounced_at timestamptz,
  complained_at timestamptz,
  failed_at timestamptz,
  last_event_at timestamptz,
  is_demo boolean not null default false
);
create index emails_requested_idx on emails(requested_at desc);
create index emails_to_idx on emails(lower(to_email));

create table email_events (
  id uuid primary key default gen_random_uuid(),
  svix_id text not null unique,
  email_id uuid references emails(id),
  resend_id text,
  type text not null,
  payload jsonb not null,
  occurred_at timestamptz,
  received_at timestamptz not null default now()
);

create table email_suppressions (
  email text primary key,
  reason text not null,
  created_at timestamptz not null default now()
);

-- Tutorials -----------------------------------------------------------------
create table tutorials (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null,
  category text not null check (category in ('np-binder','nurse-binder','printing-assembly','digital-files')),
  summary text not null default '',
  instructions jsonb not null default '{"type":"doc","content":[]}',
  transcript text not null default '',
  status text not null default 'draft' check (status in ('draft','published','unpublished','archived')),
  featured boolean not null default false,
  display_order integer not null default 0,
  thumbnail_key text,
  thumbnail_type text,
  video_provider text check (video_provider in ('mux','local','embed')),
  video_status text not null default 'none' check (video_status in ('none','uploading','processing','ready','errored')),
  video_error text not null default '',
  duration_seconds numeric,
  video_key text,
  poster_key text,
  mux_upload_id text,
  mux_asset_id text,
  mux_public_playback_id text,
  mux_signed_playback_id text,
  embed_url text,
  is_placeholder boolean not null default false,
  created_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  archived_at timestamptz
);

create table tutorial_captions (
  id uuid primary key default gen_random_uuid(),
  tutorial_id uuid not null references tutorials(id) on delete cascade,
  label text not null,
  srclang text not null,
  vtt text not null,
  unique (tutorial_id, srclang)
);

create table tutorial_products (
  tutorial_id uuid not null references tutorials(id) on delete cascade,
  product_id uuid not null references products(id) on delete cascade,
  primary key (tutorial_id, product_id)
);

create table video_uploads (
  id uuid primary key default gen_random_uuid(),
  tutorial_id uuid not null references tutorials(id) on delete cascade,
  provider text not null,
  status text not null default 'created' check (status in ('created','uploading','uploaded','processing','ready','failed')),
  file_name text not null default '',
  content_type text not null default '',
  bytes bigint,
  error text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Audit ---------------------------------------------------------------------
create table audit_log (
  id bigserial primary key,
  actor_id text,
  actor_email text,
  action text not null,
  entity_type text not null,
  entity_id text,
  summary text not null,
  data jsonb not null default '{}',
  ip text,
  created_at timestamptz not null default now()
);
create index audit_log_created_idx on audit_log(created_at desc);
create trigger audit_log_immutable before update or delete on audit_log
  for each row execute function forbid_change();
insert into schema_migrations (name) values ('001_core.sql');

-- 002_demo_keys.sql
-- Stable keys for labeled demo orders, so loading demo content twice never
-- creates duplicates. Real orders leave this empty.
alter table orders add column if not exists demo_key text;
create unique index if not exists orders_demo_key_unique on orders(demo_key) where demo_key is not null;
alter table orders drop constraint if exists orders_demo_key_only_for_demo;
alter table orders add constraint orders_demo_key_only_for_demo check (demo_key is null or is_demo);
insert into schema_migrations (name) values ('002_demo_keys.sql');

-- 003_serverless.sql
-- Serverless hosting (Vercel): state that used to live in one long running
-- process now lives in the database so every function instance shares it.

-- Fixed window rate limits shared by all instances.
create table if not exists rate_limits (
  key text primary key,
  count integer not null,
  reset_at timestamptz not null
);
create index if not exists rate_limits_reset_idx on rate_limits(reset_at);

-- When a dispatcher claimed an email. A claim older than a few minutes means
-- the function stopped mid send; the row is safely requeued (Resend
-- idempotency keys stop a second delivery).
alter table emails add column if not exists claimed_at timestamptz;

-- Direct to storage uploads. The server records who may upload what, where,
-- before handing out a one path upload URL, and only attaches the object after
-- checking its real size and type.
create table if not exists storage_uploads (
  id uuid primary key default gen_random_uuid(),
  purpose text not null check (purpose in ('product_image','product_file','tutorial_thumbnail','tutorial_video')),
  target_id uuid not null,
  image_kind text,
  alt text not null default '',
  storage_key text not null unique,
  file_name text not null,
  declared_size bigint not null,
  declared_type text not null default '',
  status text not null default 'pending' check (status in ('pending','completed','rejected')),
  video_upload_id uuid,
  error text not null default '',
  created_by text not null,
  created_at timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists storage_uploads_pending_idx on storage_uploads(created_at) where status = 'pending';
insert into schema_migrations (name) values ('003_serverless.sql');

-- 004_marketing.sql
-- Marketing: owner managed banners and the Nurse Kin popup.
-- Copy is plain text with preset themes (no HTML). Times are stored as
-- timestamptz (UTC); the admin enters them in their own timezone.

create table if not exists marketing_banners (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  style text not null check (style in ('announcement','strip','image')),
  placement text not null check (placement in ('top','below_hero','above_freebies')),
  check ((style = 'announcement') = (placement = 'top')),
  headline text not null default '',
  body text not null default '',
  button_label text not null default '',
  link text not null default '',
  image_key text,
  image_type text,
  image_alt text not null default '',
  theme text not null default 'blush' check (theme in ('blush','raspberry','ivory','sage')),
  icon text not null default 'none' check (icon in ('none','heart','sparkles','gift','download','truck','star','tag')),
  -- A coupon code is only ever shown after it was checked against a real,
  -- active Stripe promotion code. The offer text comes from Stripe's terms.
  coupon_code text not null default '',
  coupon_offer text not null default '',
  coupon_expires_at timestamptz,
  coupon_checked_at timestamptz,
  active boolean not null default true,
  status text not null default 'draft' check (status in ('draft','published','archived')),
  starts_at timestamptz,
  ends_at timestamptz,
  check (ends_at is null or starts_at is null or ends_at > starts_at),
  priority integer not null default 10 check (priority between 1 and 100),
  pages text[] not null default '{all}',
  dismissible boolean not null default true,
  -- Raising this shows the banner again to visitors who closed it.
  dismiss_version integer not null default 1,
  published_at timestamptz,
  created_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists marketing_banners_live_idx on marketing_banners(placement, priority) where status = 'published';

-- Single row: the Nurse Kin popup. Stays a draft until the owner supplies
-- the real destination and approved copy.
create table if not exists marketing_popup (
  id text primary key default 'nurse_kin' check (id = 'nurse_kin'),
  enabled boolean not null default false,
  status text not null default 'draft' check (status in ('draft','published')),
  headline text not null default '',
  body text not null default '',
  cta_label text not null default '',
  url text not null default '',
  image_key text,
  image_type text,
  image_alt text not null default '',
  theme text not null default 'blush' check (theme in ('blush','raspberry','ivory','sage')),
  delay_seconds integer not null default 30 check (delay_seconds between 10 and 300),
  scroll_percent integer not null default 50 check (scroll_percent = 0 or scroll_percent between 20 and 90),
  suppress_days integer not null default 7 check (suppress_days between 1 and 90),
  pages text[] not null default '{home,shop,collections,extra,freebies,tutorials,story}',
  starts_at timestamptz,
  ends_at timestamptz,
  check (ends_at is null or starts_at is null or ends_at > starts_at),
  -- Raising this lets the popup show again in browsers that closed or clicked it.
  campaign_version integer not null default 1,
  published_at timestamptz,
  updated_by text,
  updated_at timestamptz not null default now()
);
insert into marketing_popup (id) values ('nurse_kin') on conflict (id) do nothing;

-- Aggregate counts only: no visitor identifiers are stored.
create table if not exists marketing_stats (
  kind text not null check (kind in ('banner','popup')),
  item_id text not null,
  version integer not null,
  day date not null,
  views integer not null default 0,
  clicks integer not null default 0,
  dismissals integer not null default 0,
  primary key (kind, item_id, version, day)
);

-- Banner and popup images go through the same checked direct uploads.
alter table storage_uploads drop constraint if exists storage_uploads_purpose_check;
alter table storage_uploads add constraint storage_uploads_purpose_check
  check (purpose in ('product_image','product_file','tutorial_thumbnail','tutorial_video','banner_image','popup_image'));
insert into schema_migrations (name) values ('004_marketing.sql');

-- 005_quiz_reviews_story_previews.sql
-- Resource quiz, verified reviews, Our Story content, approved product
-- previews, and the Nurse Kin launcher (replacing the automatic popup).

-- Resource quiz. Edits go to "draft"; the storefront only ever reads
-- "published", which changes only when the owner presses Publish.
create table if not exists quizzes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  status text not null default 'draft' check (status in ('draft','published','archived')),
  draft jsonb not null,
  published jsonb,
  version integer not null default 0,
  published_at timestamptz,
  created_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- One storefront quiz at a time.
create unique index if not exists quizzes_one_published on quizzes ((status)) where status = 'published';

-- Aggregate counts only: no answers and no visitor identifiers are stored.
create table if not exists quiz_stats (
  quiz_id uuid not null references quizzes(id) on delete cascade,
  version integer not null,
  day date not null,
  starts integer not null default 0,
  completions integer not null default 0,
  product_clicks integer not null default 0,
  primary key (quiz_id, version, day)
);

-- Verified purchase reviews. One per customer per product.
create table if not exists reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  user_id text not null references "user"(id) on delete cascade,
  rating integer not null check (rating between 1 and 5),
  title text not null,
  body text not null,
  display_name text not null,
  status text not null default 'pending' check (status in ('pending','published','rejected')),
  moderation_reason text not null default '',
  moderated_by text,
  moderated_at timestamptz,
  owner_reply text not null default '',
  owner_reply_at timestamptz,
  report_count integer not null default 0,
  report_reasons text[] not null default '{}',
  reported_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, product_id)
);
create index if not exists reviews_product_idx on reviews(product_id, status);

-- Owner managed page content (Our Story). Draft and published copies.
create table if not exists site_content (
  key text primary key,
  draft jsonb not null default '{}',
  published jsonb,
  published_at timestamptz,
  updated_by text,
  updated_at timestamptz not null default now()
);

-- Product previews: selected sample pages and cropped details are separate,
-- watermarked images the owner approves. Paid files are never used directly.
alter table product_images drop constraint if exists product_images_kind_check;
alter table product_images add constraint product_images_kind_check check (kind in ('gallery','sample','detail'));
alter table product_images add column if not exists approved boolean not null default true;
alter table products add column if not exists whats_included text[] not null default '{}';
alter table products add column if not exists walkthrough_tutorial_id uuid references tutorials(id) on delete set null;

-- Nurse Kin: a launcher the visitor opens, never an automatic popup.
alter table marketing_popup add column if not exists launcher_label text not null default '';

alter table storage_uploads drop constraint if exists storage_uploads_purpose_check;
alter table storage_uploads add constraint storage_uploads_purpose_check
  check (purpose in ('product_image','product_file','tutorial_thumbnail','tutorial_video','banner_image','popup_image','story_portrait'));
insert into schema_migrations (name) values ('005_quiz_reviews_story_previews.sql');

-- 006_email_automations.sql
-- Email automations: download reminders and review requests, plus the
-- shipment details they depend on (which items each shipment holds, and a
-- confirmed delivery time with its source). All three automations start
-- switched off. Times are timestamptz (UTC).

create table if not exists email_automations (
  kind text primary key check (kind in ('download_reminder','digital_review','physical_review')),
  enabled boolean not null default false,
  -- Days after the starting event: payment for digital, confirmed delivery for physical.
  delay_days integer not null check (delay_days between 1 and 90),
  updated_at timestamptz not null default now(),
  updated_by text
);
insert into email_automations (kind, delay_days) values
  ('download_reminder', 3), ('digital_review', 7), ('physical_review', 14)
on conflict (kind) do nothing;

-- One row per purchased item and automation. The dedupe key makes repeated
-- payment or delivery events, retries and overlapping jobs harmless:
--   download_reminder:<order item>   at most one reminder per purchased item
--   review:<customer>:<product>      at most one review request per customer and product
create table if not exists email_jobs (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('download_reminder','digital_review','physical_review')),
  dedupe_key text not null unique,
  status text not null default 'scheduled' check (status in ('scheduled','held','processing','sent','skipped','failed','canceled')),
  -- Why a request is held: waiting for confirmed delivery, the automation is
  -- switched off, or a known delivery problem.
  hold_reason text not null default '' check (hold_reason in ('','awaiting_delivery','automation_off','delivery_problem')),
  status_reason text not null default '',
  user_id text references "user"(id) on delete cascade,
  order_id uuid not null references orders(id),
  order_item_id uuid not null references order_items(id),
  product_id uuid not null references products(id),
  shipment_id uuid references shipments(id),
  -- The confirmed payment or delivery time the delay counts from.
  start_at timestamptz,
  due_at timestamptz,
  attempts integer not null default 0,
  claimed_at timestamptz,
  last_error text not null default '',
  email_id uuid references emails(id),
  sent_at timestamptz,
  canceled_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists email_jobs_due_idx on email_jobs(due_at) where status = 'scheduled';
create index if not exists email_jobs_order_idx on email_jobs(order_id);
create index if not exists email_jobs_kind_idx on email_jobs(kind, status, created_at desc);

-- Which items (and how many) each shipment holds, for split shipments.
-- Shipments created before this existed cover every physical item of their order.
create table if not exists shipment_items (
  shipment_id uuid not null references shipments(id) on delete cascade,
  order_item_id uuid not null references order_items(id),
  quantity integer not null check (quantity > 0),
  primary key (shipment_id, order_item_id)
);

-- Confirmed delivery: where it came from (carrier, printful, admin) and why
-- (an admin must give a reason). "Shipped" or an estimated date never counts.
alter table shipments add column if not exists delivery_source text not null default '';
alter table shipments add column if not exists delivery_note text not null default '';
alter table shipments add column if not exists problem text not null default '';
alter table shipments add column if not exists status_at timestamptz;
alter table shipments add column if not exists updated_at timestamptz not null default now();

-- Tracking events from a future Printful or carrier connection, stored once.
create table if not exists shipment_events (
  id uuid primary key default gen_random_uuid(),
  shipment_id uuid references shipments(id),
  source text not null,
  external_event_id text not null,
  status text not null,
  occurred_at timestamptz not null,
  detail text not null default '',
  outcome text not null default '',
  payload jsonb not null default '{}',
  received_at timestamptz not null default now(),
  unique (source, external_event_id)
);

-- Separate opt outs. Receipts and account security emails are not affected.
alter table customer_profiles add column if not exists download_reminders boolean not null default true;
alter table customer_profiles add column if not exists review_requests boolean not null default true;
insert into schema_migrations (name) values ('006_email_automations.sql');

-- 3. Row level security on every store table. The store's server is the
-- table owner and is unaffected; Supabase's public Data API sees nothing.
do $$ declare t record; begin
  for t in select tablename from pg_tables where schemaname = 'public' and not rowsecurity loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

-- 4. Two PRIVATE storage buckets: purchasable files, and media (photos,
-- sample pages, tutorial videos). Skipped outside Supabase.
do $$ begin
  if exists (select 1 from pg_namespace where nspname = 'storage') then
    insert into storage.buckets (id, name, public, file_size_limit)
    values ('product-files', 'product-files', false, 52428800), ('media', 'media', false, 52428800)
    on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit;
  end if;
end $$;

commit;
